import{_ as e,o,c as s,a2 as r}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Manual de Usuario","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/index.md","filePath":"es-ES/user-guide/index.md","lastUpdated":1786468666000}'),t={name:"es-ES/user-guide/index.md"};function i(n,a,l,d,c,u){return o(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="manual-de-usuario" tabindex="-1">Manual de Usuario <a class="header-anchor" href="#manual-de-usuario" aria-label="Permalink to &quot;Manual de Usuario&quot;">​</a></h1><p>Lertaro es un lanzador de búsqueda de archivos rápido y centrado en el teclado para Windows. Indexa tus unidades locales (NTFS y ReFS a través de sus journals de cambios, otros sistemas de archivos vigilándolos directamente) y los recursos compartidos de red en segundo plano, y luego te permite saltar a cualquier archivo, carpeta o aplicación en una fracción de segundo.</p><p>Este manual cubre todo lo que un usuario habitual necesita:</p><ul><li><strong><a href="./getting-started.html">Primeros pasos</a></strong> — instalar Lertaro y entender sus tres ventanas de búsqueda (principal, rápida, en línea).</li><li><strong><a href="./search-syntax.html">Sintaxis de búsqueda</a></strong> — coincidencia difusa, operadores de exclusión/exacto/prefijo/sufijo, grupos OR, segmentación por unidad, modo de ruta y alias en pinyin para nombres de archivo en chino.</li><li><strong><a href="./hotkeys.html">Atajos de teclado</a></strong> — cada atajo configurable y cada tecla fija, con sus asignaciones predeterminadas.</li><li><strong><a href="./actions-and-preview.html">Menú de acciones y vista previa</a></strong> — la lista de acciones al estilo del clic derecho y el panel de vista previa QuickLook.</li><li><strong><a href="./space-analyzer.html">Analizador de espacio</a></strong> — un mapa de árbol rápido que usa los índices existentes para mostrar el espacio relativo de archivos y carpetas.</li><li><strong><a href="./instant-answers.html">Respuestas instantáneas y atajos de palabra clave</a></strong> — la calculadora, las variables de entorno, los atajos de comandos y los plugins activados por palabra clave como Gestor de procesos, Cambio de ventana, Datos del navegador, Búsqueda de configuración, Búsqueda web y Traducción.</li><li><strong><a href="./cli.html">Búsqueda por línea de comandos (lff)</a></strong> — el complemento de línea de comandos al estilo fzf para buscar desde una terminal.</li><li><strong><a href="./uri-protocol.html">Protocolo URI (lertaro://)</a></strong> — saltar directamente a una búsqueda o a un ajuste concreto desde un enlace, otra aplicación o un script.</li><li><strong><a href="./file-manager-support.html">Gestores de archivos compatibles</a></strong> — en qué gestores de archivos y diálogos de selección de archivos puede acoplarse Lertaro, desde cuáles puede activar la Navegación rápida, o de cuáles puede detectar la carpeta actual.</li><li><strong><a href="./settings/">Referencia de configuración</a></strong> — cada página, pestaña y opción de configuración, detallada.</li><li><strong><a href="./troubleshooting.html">Solución de problemas</a></strong> — problemas habituales y cómo solucionarlos.</li><li><strong><a href="./donate.html">Donar</a></strong> — si Lertaro te ha resultado útil.</li></ul><p>Si estás configurando Lertaro por primera vez, empieza por <strong>Primeros pasos</strong>.</p>',5)])])}const m=e(t,[["render",i]]);export{g as __pageData,m as default};
